#!/bin/sh
# Generated by FWShift: a Google Cloud network firewall policy, created with gcloud. Read the report first: what is
# not written is listed there.
#
#   DRY_RUN=1 sh THIS_FILE                              prints the commands; needs no access to Google Cloud
#   GCLOUD_OPTS='--project my-project' sh THIS_FILE     creates the policy and its rules
#
# The policy is associated with no network: nothing changes for any traffic until you associate it:
#   gcloud compute network-firewall-policies associations create --firewall-policy fwshift --network NETWORK --global-firewall-policy
# It decides every connection of that network. Set the network's enforcement order to BEFORE_CLASSIC_FIREWALL, or
# the VPC firewall rules of the network decide first. A policy of the same name stops the script before anything is
# created; a command gcloud refuses stops it where it is (delete the policy and run it again).
set -u
DRY_RUN="${DRY_RUN:-}"
GCLOUD_OPTS="${GCLOUD_OPTS:-}"
POLICY=fwshift
fail() { printf 'FAILED: %s\n' "$*" >&2; exit 1; }
run() {
  if [ -n "$DRY_RUN" ]; then printf 'gcloud' >&2; printf ' %s' "$@" >&2; printf '\n' >&2; return 0; fi
  gcloud "$@" $GCLOUD_OPTS --quiet >/dev/null || fail "gcloud $1 $2 $3 $4"
}
if [ -z "$DRY_RUN" ] && gcloud compute network-firewall-policies describe "$POLICY" --global $GCLOUD_OPTS >/dev/null 2>&1; then
  fail "a network firewall policy named $POLICY exists already; nothing was created"
fi

run compute network-firewall-policies create "$POLICY" --global '--description=Generated by FWShift; review the conversion report before associating it'

run compute network-firewall-policies rules create 1000 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=192.0.2.128/25 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all --enable-logging '--description=global 1'
run compute network-firewall-policies rules create 1010 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=192.0.2.128/25 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all --enable-logging '--description=global 1'
run compute network-firewall-policies rules create 1020 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=allow --src-ip-ranges=10.10.0.0/24,10.20.0.0/24,10.30.0.0/24 --dest-ip-ranges=10.10.0.254/32,10.20.0.254/32,10.30.0.254/32,203.0.113.2/32 --layer4-configs=icmp --enable-logging '--description=local 2'
run compute network-firewall-policies rules create 1030 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=allow --src-ip-ranges=10.10.0.0/24,10.20.0.0/24,10.30.0.0/24 --dest-ip-ranges=10.10.0.254/32,10.20.0.254/32,10.30.0.254/32,203.0.113.2/32 --layer4-configs=icmp --enable-logging '--description=local 2'
run compute network-firewall-policies rules create 1040 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=198.51.100.0/24 --layer4-configs=all --enable-logging '--description=local 3'
run compute network-firewall-policies rules create 1050 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=198.51.100.0/24 --layer4-configs=all --enable-logging '--description=local 3'
run compute network-firewall-policies rules create 1060 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=allow --src-ip-ranges=10.10.0.0/24,10.20.0.0/24,10.30.0.0/24 --dest-ip-ranges=0.0.0.0/5,8.0.0.0/7,10.0.0.0/13,10.8.0.0/15,10.10.1.0/24,10.10.2.0/23,10.10.4.0/22,10.10.8.0/21,10.10.16.0/20,10.10.32.0/19,10.10.64.0/18,10.10.128.0/17,10.11.0.0/16,10.12.0.0/14,10.16.0.0/14,10.20.1.0/24,10.20.2.0/23,10.20.4.0/22,10.20.8.0/21,10.20.16.0/20,10.20.32.0/19,10.20.64.0/18,10.20.128.0/17,10.21.0.0/16,10.22.0.0/15,10.24.0.0/14,10.28.0.0/15,10.30.1.0/24,10.30.2.0/23,10.30.4.0/22,10.30.8.0/21,10.30.16.0/20,10.30.32.0/19,10.30.64.0/18,10.30.128.0/17,10.31.0.0/16,10.32.0.0/11,10.64.0.0/10,10.128.0.0/9,11.0.0.0/8,12.0.0.0/6,16.0.0.0/4,32.0.0.0/3,64.0.0.0/2,128.0.0.0/1 --layer4-configs=tcp:80,tcp:443,tcp:8080-8090 --enable-logging '--description=local 4'
run compute network-firewall-policies rules create 1070 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=allow --src-ip-ranges=10.10.0.0/24,10.20.0.0/24,10.30.0.0/24 --dest-ip-ranges=0.0.0.0/5,8.0.0.0/7,10.0.0.0/13,10.8.0.0/15,10.10.1.0/24,10.10.2.0/23,10.10.4.0/22,10.10.8.0/21,10.10.16.0/20,10.10.32.0/19,10.10.64.0/18,10.10.128.0/17,10.11.0.0/16,10.12.0.0/14,10.16.0.0/14,10.20.1.0/24,10.20.2.0/23,10.20.4.0/22,10.20.8.0/21,10.20.16.0/20,10.20.32.0/19,10.20.64.0/18,10.20.128.0/17,10.21.0.0/16,10.22.0.0/15,10.24.0.0/14,10.28.0.0/15,10.30.1.0/24,10.30.2.0/23,10.30.4.0/22,10.30.8.0/21,10.30.16.0/20,10.30.32.0/19,10.30.64.0/18,10.30.128.0/17,10.31.0.0/16,10.32.0.0/11,10.64.0.0/10,10.128.0.0/9,11.0.0.0/8,12.0.0.0/6,16.0.0.0/4,32.0.0.0/3,64.0.0.0/2,128.0.0.0/1 --layer4-configs=tcp:80,tcp:443,tcp:8080-8090 --enable-logging '--description=local 4'
run compute network-firewall-policies rules create 1080 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=10.10.0.0/24,10.20.0.0/24,10.30.0.0/24 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=tcp:113 --enable-logging '--description=local 6'
run compute network-firewall-policies rules create 1090 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=10.10.0.0/24,10.20.0.0/24,10.30.0.0/24 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=tcp:113 --enable-logging '--description=local 6'
run compute network-firewall-policies rules create 1100 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=allow --src-ip-ranges=10.30.0.0/24 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=200 --enable-logging '--description=local 12'
run compute network-firewall-policies rules create 1110 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=allow --src-ip-ranges=10.30.0.0/24 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=200 --enable-logging '--description=local 12'
