run compute network-firewall-policies rules create 1150 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all --enable-logging '--description=local 16'
run compute network-firewall-policies rules create 1160 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=::/0 --dest-ip-ranges=::/0 --layer4-configs=all --enable-logging '--description=local 16'
run compute network-firewall-policies rules create 1170 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=::/0 --dest-ip-ranges=::/0 --layer4-configs=all --enable-logging '--description=local 16'
run compute network-firewall-policies rules create 1180 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all --description=fwshift-default-deny
run compute network-firewall-policies rules create 1190 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all --description=fwshift-default-deny
run compute network-firewall-policies rules create 1200 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=::/0 --dest-ip-ranges=::/0 --layer4-configs=all --description=fwshift-default-deny
run compute network-firewall-policies rules create 1210 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=::/0 --dest-ip-ranges=::/0 --layer4-configs=all --description=fwshift-default-deny

# Not written:
#   local 1: the source of the rule is in zone in, and a rule of Google Cloud names no zone: give the networks behind in with --zone-network
#   local 5: the source of the rule is in zone in, and a rule of Google Cloud names no zone: give the networks behind in with --zone-network
#   local 8: the source of the rule is in zone out, and a rule of Google Cloud names no zone: give the networks behind out with --zone-network
#   local 9: the source of the rule is in zone out, and a rule of Google Cloud names no zone: give the networks behind out with --zone-network
#   local 10: the source of the rule is in zone lab, and a rule of Google Cloud names no zone: give the networks behind lab with --zone-network
#   local 11: source user match staff@corp.example is not converted
#   local 13: host name object updates.example.com: the rules are written with addresses
#   local 15: host name object www.example.org: the rules are written with addresses

echo 'Done. Associate the policy with the network when you are ready; until then nothing changes.' >&2
